import requests
import os
from typing import Dict

def send_completion_notification(storage_results: Dict) -> str:
    """Telegram értesítés a pipeline befejezéséről"""

    telegram_token = os.getenv('TELEGRAM_BOT_TOKEN')
    chat_id = os.getenv('TELEGRAM_CHAT_ID')

    if not telegram_token or not chat_id:
        return "Telegram credentials not configured"

    # Üzenet összeállítása
    message = f"""🔬 AI Research Pipeline - Futás befejezve

📊 Eredmények:
• Új bejegyzések: {storage_results.get('total_entries', 0)}
• ChromaDB: {storage_results.get('chromadb_status', 'unknown')}
• Backup: {storage_results.get('backup_status', 'unknown')}

📁 Backup fájl: {storage_results.get('backup_file', 'N/A')}

✅ A tudásbázis frissítve!"""

    # Telegram API hívás
    url = f"https://api.telegram.org/bot{telegram_token}/sendMessage"
    payload = {
        'chat_id': chat_id,
        'text': message,
        'parse_mode': 'HTML'
    }

    try:
        response = requests.post(url, json=payload, timeout=10)
        if response.status_code == 200:
            return "Notification sent successfully"
        else:
            return f"Telegram API error: {response.status_code}"
    except Exception as e:
        return f"Notification error: {str(e)}"

# Langflow integration
result = send_completion_notification(storage_results)
